package e.e.a;
import java.util.*;import org.json.*;
public final class Settings183Test {
 static void require(boolean b,String message){if(!b)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{
  long now=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ssZ").parse("2026-10-12 15:00:00+0900").getTime();
  require(SearchFilterRules.since(1,now).equals("2026-10-11T15:00:00+09:00"),"rolling 24 hours");require(SearchFilterRules.since(4,now).equals("2026-04-12T15:00:00+09:00"),"six calendar months");require(SearchFilterRules.since(7,now).equals("2021-10-12T15:00:00+09:00"),"five calendar years");
  for(int i=0;i<8;i++){String url=SearchFilterRules.url(new int[]{0,0,0,i},"a b&c");require(url.contains("keyword=a+b%26c"),"query escaping");JSONObject video=new JSONObject().put("duration",i==2?1200:i==7?3600:SearchFilterRules.max(i)>0?SearchFilterRules.max(i):100);require(SearchFilterRules.matches(video,url),"inclusive duration boundary "+i);if(SearchFilterRules.max(i)>0){video.put("duration",SearchFilterRules.max(i)+1);require(!SearchFilterRules.matches(video,url),"exclude too-long video");}if(SearchFilterRules.min(i)>0){video.put("duration",SearchFilterRules.min(i)-1);require(!SearchFilterRules.matches(video,url),"exclude too-short video");}}
  SettingsBackupData.TYPES.put("comment_fps","string");SettingsBackupData.VALUES.put("comment_fps",new HashSet<>(Arrays.asList("30","60","90","120")));SettingsBackupData.TYPES.put("comment_hide","boolean");SettingsBackupData.TYPES.put("search_Time","int");SettingsBackupData.TYPES.put("save_cookie","string");Map<String,Object> prefs=new HashMap<>();prefs.put("comment_fps","90");prefs.put("comment_hide",true);prefs.put("search_Time",7);prefs.put("save_cookie","test-session");prefs.put("cache_tree_uri","content://old-device");prefs.put("labs_cashe_speed_up",true);JSONObject backup=SettingsBackupData.encode(prefs);require(!backup.toString().contains("test-session")&&!backup.toString().contains("old-device")&&!backup.toString().contains("labs_cashe"),"only portable settings exported");Map<String,Object> restored=SettingsBackupData.decode(backup);require(restored.get("comment_fps").equals("90")&&restored.get("comment_hide").equals(true)&&restored.get("search_Time").equals(7),"typed round trip");
  JSONObject bad=new JSONObject(backup.toString());bad.getJSONObject("settings").getJSONObject("comment_hide").put("type","string").put("value","true");try{SettingsBackupData.decode(bad);throw new AssertionError("invalid type accepted");}catch(java.io.IOException expected){}
  bad=new JSONObject(backup.toString());bad.getJSONObject("settings").getJSONObject("comment_fps").put("value","999");try{SettingsBackupData.decode(bad);throw new AssertionError("invalid enum accepted");}catch(java.io.IOException expected){}
  for(Object value:new Object[]{1.5,"7",4294967296L}){bad=new JSONObject(backup.toString());bad.getJSONObject("settings").getJSONObject("search_Time").put("value",value);try{SettingsBackupData.decode(bad);throw new AssertionError("invalid numeric setting accepted");}catch(java.io.IOException expected){}}
  JSONObject thread=new JSONObject().put("id","second").put("isDefaultPostTarget",true).put("is184Forced",true);JSONObject comment=new JSONObject().put("threads",new JSONArray().put(new JSONObject().put("id","first")).put(thread));JSONArray targets=new JSONArray().put(new JSONObject().put("id","first").put("fork","main"));require(PostingRules.thread(comment,targets).optString("id").equals("second"),"designated channel posting thread");require(PostingRules.videoId("1234567890","so12","so12").equals("1234567890"),"numeric canonical client watch identity");
  Object historyRow=new Object();HistorySupport.capture(historyRow,new JSONObject(),new JSONObject().put("owner",new JSONObject().put("name","creator")));java.lang.reflect.Field owners=HistorySupport.class.getDeclaredField("OWNERS");owners.setAccessible(true);require("creator".equals(((Map)owners.get(null)).get(historyRow)),"account record owner fallback");HistorySupport.capture(historyRow,new JSONObject().put("channel",new JSONObject().put("name","channel creator")),new JSONObject());require("channel creator".equals(((Map)owners.get(null)).get(historyRow)),"history channel creator");
  System.out.println("Search boundaries, date periods, typed backup validation and channel posting rules passed");
 }
}
